41	
42	    /**
43	     * Resolve an owner's possible-duplicate flag, coalescing a {@code null} stored value
44	     * (e.g. for owners created before the flag existed) to {@code false} so the response
45	     * always carries an explicit boolean.
46	     */
47	    default Boolean formatPossibleDuplicate(Owner owner) {
48	        if (owner == null) {
49	            return null;
50	        }
51	        return Boolean.TRUE.equals(owner.getPossibleDuplicate());
52	    }
53	
54	    /**
55	     * Derive an owner's age band from its {@code birthDate}, measured as the owner's age in whole
56	     * years on its {@code registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18
57	     * through 64, and {@code "SENIOR"} at 65 and over. Returns {@code null} when the owner, its
58	     * birth date or its registration date is absent, since the band cannot be derived without both
59	     * dates.
60	     */
61	    default String formatAgeBand(Owner owner) {
62	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
63	            return null;
64	        }
65	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
66	        if (age < 18) {
67	            return "MINOR";
68	        }
69	        if (age < 65) {
70	            return "ADULT";
71	        }
72	        return "SENIOR";
73	    }
74	
75	    /**
76	     * Derive an owner's preferred contact channel from its stored contact details:
77	     * {@code "EMAIL"} when a (non-blank) email address is present, otherwise {@code "PHONE"}.
78	     */
79	    default String formatContactPreference(Owner owner) {
80	        if (owner == null) {
81	            return null;
82	        }
83	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
84	        return hasEmail ? "EMAIL" : "PHONE";
85	    }
86	
87	    /**
88	     * Resolve an owner's bulk-signup warning flag, coalescing a {@code null} stored value
89	     * (e.g. for owners created before the flag existed) to {@code false} so the response
90	     * always carries an explicit boolean.
91	     */
92	    default Boolean formatBulkSignupWarning(Owner owner) {
93	        if (owner == null) {
94	            return null;
95	        }
96	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
97	    }
98	
99	    /**
100	     * Derive an owner's locality from its region-and-hash identity: the {@code <REGION>} segment
101	     * of the {@code customerCode} (the part before the first hyphen), which is the region code
102	     * derived from the owner's postcode. For an owner that has not yet been assigned a customer
103	     * code, the region is derived directly from the postcode (see {@link Regions#forPostcode}),
104	     * yielding the same value the code would carry. Returns {@code null} only when the owner
105	     * itself is {@code null}.
106	     */
107	    default String formatLocality(Owner owner) {
108	        if (owner == null) {
109	            return null;
110	        }
111	        String code = owner.getCustomerCode();
112	        if (code != null) {
