121	     * region-to-timezone table (see {@link Regions#timezoneForRegion}): NSW -> Australia/Sydney,
122	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane. Returns {@code null} when the owner
123	     * is {@code null} or its region is not in the table.
124	     */
125	    default String formatTimezone(Owner owner) {
126	        if (owner == null) {
127	            return null;
128	        }
129	        return Regions.timezoneForRegion(formatLocality(owner));
130	    }
131	
132	    /**
133	     * Compute an owner's membership points. Points start at {@code 0} and gain: {@code 2} when an
134	     * email address is present; {@code 1} when the owner has no namesakes (its
135	     * {@code namesakeCount} is {@code 0}); {@code 2} for a household of three or more members (the
136	     * owner plus its pets); and {@code 3} when the owner's tenure (days elapsed since its
137	     * {@code registrationDate}) exceeds {@code 365}. A null or absent namesake count is treated as
138	     * not being zero, so it contributes nothing.
139	     */
140	    default Integer formatMembershipPoints(Owner owner) {
141	        if (owner == null) {
142	            return null;
143	        }
144	        int points = 0;
145	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
146	        if (hasEmail) {
147	            points += 2;
148	        }
149	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
150	        if (uniqueName) {
151	            points += 1;
152	        }
153	        int householdSize = 1 + (owner.getPets() == null ? 0 : owner.getPets().size());
154	        if (householdSize >= 3) {
155	            points += 2;
156	        }
157	        LocalDate registrationDate = owner.getRegistrationDate();
158	        if (registrationDate != null && ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365) {
159	            points += 3;
160	        }
161	        return points;
162	    }
163	
164	    /**
165	     * Determine an owner's membership level, a number from {@code 1} to {@code 4} derived from its
166	     * membership points (see {@link #formatMembershipPoints(Owner)}): level {@code 1} for
167	     * {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3}, {@code 3} for {@code 4}-{@code 5}
