194	        if (owner == null || owner.getCustomerCode() == null) {
195	            return null;
196	        }
197	        String code = owner.getCustomerCode();
198	        int sum = 0;
199	        boolean dbl = true;
200	        for (int i = code.length() - 1; i >= 0; i--) {
201	            char c = code.charAt(i);
202	            if (c < '0' || c > '9') {
203	                continue;
204	            }
205	            int d = c - '0';
206	            if (dbl) {
207	                d *= 2;
208	                if (d > 9) {
